
DO $rehearsal$
DECLARE
    v_total_countries INT;
    v_covered_countries INT;
    v_duplicates INT;
BEGIN
    -- Execute the migration statements
    -- Migration 000018: Global Tax Authorities Canonical Data Load


-- Pre-requisites: Ensure applicability_scopes and jurisdictions match expected schema
CREATE TABLE IF NOT EXISTS catalog.applicability_scopes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    country_id UUID NOT NULL REFERENCES catalog.countries(id),
    scope_type TEXT NOT NULL CHECK (scope_type IN ('COUNTRY_WIDE', 'GEOGRAPHIC')),
    priority INT NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE')),
    effective_from TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    effective_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE catalog.jurisdictions ADD COLUMN IF NOT EXISTS country_id UUID REFERENCES catalog.countries(id);
ALTER TABLE catalog.jurisdictions ADD COLUMN IF NOT EXISTS applicability_scope_id UUID REFERENCES catalog.applicability_scopes(id);

ALTER TABLE catalog.tax_authorities DROP CONSTRAINT IF EXISTS tax_authorities_tax_type_check;
ALTER TABLE catalog.tax_authorities ADD CONSTRAINT tax_authorities_tax_type_check CHECK (tax_type IN ('GST', 'VAT', 'SALES_TAX', 'WITHHOLDING', 'TDS', 'CUSTOMS', 'EXCISE', 'NOT_APPLICABLE', 'UNRESOLVED'));



    -- Verify country coverage
    SELECT COUNT(*) INTO v_total_countries FROM catalog.countries;
    SELECT COUNT(DISTINCT country_id) INTO v_covered_countries FROM catalog.tax_authorities;
    
    RAISE NOTICE 'Total countries: %', v_total_countries;
    RAISE NOTICE 'Covered countries: %', v_covered_countries;
    
    IF v_total_countries != v_covered_countries THEN
        RAISE EXCEPTION 'Country coverage mismatch: Expected %, got %', v_total_countries, v_covered_countries;
    END IF;

    -- Verify exact duplicates and overlaps
    SELECT COUNT(*) INTO v_duplicates
    FROM (
        SELECT country_id, tax_type, COUNT(*) 
        FROM catalog.tax_authorities 
        GROUP BY country_id, tax_type 
        HAVING COUNT(*) > 1
    ) dupes;
    
    RAISE NOTICE 'Exact duplicates found: %', v_duplicates;

    -- Force rollback
    RAISE EXCEPTION 'REHEARSAL_SUCCESS_ROLLBACK';
END $rehearsal$;
